mapper.select:
SELECT p.id, p.name, p.category_id, c.name AS category_name, p.shop_id, s.shop_name, s.merchant_id, p.price, p.price AS original_price, p.image, p.description, p.status, p.sales, p.view_point, p.create_time, (SELECT COALESCE(SUM(ps.stock), 0) FROM product_sku ps WHERE ps.product_id = p.id) AS stock FROM product p LEFT JOIN category c ON p.category_id = c.id LEFT JOIN shop s ON p.shop_id = s.id 1=1
AND p.shop_id = #{shopId}
AND p.status = #{status}
AND p.category_id = #{categoryId}
AND p.category_id IN #{cid}
AND p.name LIKE CONCAT('%', #{name}, '%')
ORDER BY p.price ASC ORDER BY p.price DESC ORDER BY p.create_time DESC ORDER BY p.create_time DESC
